@Component("modelVersion-handler")
@ProcessingGroup("modelVersion-processing-group")
public class ModelVersionEventHandler {
	
	// core constructor
	ModelVersionEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateModelVersionEvent
     */
    @EventHandler
    public void handle( CreateModelVersionEvent event) {
        entityManager.persist(new ModelVersion(event.getModelVersionId(), event.getVersion(), event.getModel(), event.getTrainingRun(), event.getEvaluationMetrics(), event.getDeployments(), event.getFeatureSets(), event.getDatasets(), event.getLifecycle(), event.getTrainingStatus()));
    }

    /*
     * @param	event UpdateModelVersionEvent
     */
    @EventHandler
    public ModelVersion handle( UpdateModelVersionEvent event) {
    	entityManager.merge(new ModelVersion(event.getModelVersionId(), event.getVersion(), event.getModel(), event.getTrainingRun(), event.getEvaluationMetrics(), event.getDeployments(), event.getFeatureSets(), event.getDatasets(), event.getLifecycle(), event.getTrainingStatus()));
    }
    
    /*
     * @param	event DeleteModelVersionEvent
     */
    @EventHandler
    public void on( DeleteModelVersionEvent event) {
    	ModelVersion entity = new ModelVersion();
   
    	// ------------------------------------------
    	// apply the ModelVersionId
    	// ------------------------------------------
    	entity.setModelVersionId( event.getModelVersionId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ModelVersionRepository modelVersionEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ModelVersionEventHandler.class.getName());

}
